import { FunctionComponent, useEffect } from 'preact/compat';
import CloseIcon from '@material-ui/icons/Close';
import CircularProgress from '@material-ui/core/CircularProgress';
import LanguageIcon from '@material-ui/icons/Language';
import ImagesIcon from '@material-ui/icons/CropOriginal';

import styles from './styles.module.scss';
import { ImageResponse } from '../../../slice/types';

const getHost = (url) => {
  try {
    return new URL(url).hostname;
  } catch (err) {
    return '';
  }
}

interface Props {
  image: ImageResponse,
  onClose: () => unknown,
}

const Popup: FunctionComponent<Props> = ({ image, onClose }: Props) => {
  useEffect(() => {
    const onKeyDown = (e) => {
      if (e.key === 'Escape') onClose();
    };

    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
    };
  }, []);

  return (
    <section className={styles.modal}>
      <div className={styles.overlay} onClick={onClose} />
      <div className={styles.modalContent}>
        <button
          type="button"
          className={styles.closeButton}
          onClick={onClose}
        >
          <CloseIcon />
        </button>

        <div className={styles.spinner}>
          <CircularProgress />
        </div>

        <a
          href={image.hostPageUrl}
          style={{ display: 'flex', justifyContent: 'center' }}
        >
          <img src={image.contentUrl} alt="" />
        </a>

        <footer className={styles.footer}>
          <div style={{ flex: 1, minWidth: 0 }}>
            <a href={image.hostPageUrl}>
              <h4 className={styles.name}>{image.name}</h4>
            </a>

            <a href={image.hostPageUrl}>
              {getHost(image.hostPageUrl)}
            </a>

            <span className={styles.mediaDimensions}>
              &nbsp;| {image.width} x {image.height}
            </span>
          </div>

          <div style={{ width: 230 }}>
            <a className={styles.button} href={image.hostPageUrl}>
              <LanguageIcon />
              Visit
            </a>
            <a className={styles.button} href={image.contentUrl}>
              <ImagesIcon />
              Open original image
            </a>
          </div>
        </footer>
      </div>
    </section>
  );
};

export default Popup;
